\pset tuples_only on
\pset format unaligned
\pset pager off
SELECT jsonb_pretty(jsonb_build_object(
 'manifest_version', 1,
 'server_version', current_setting('server_version'),
 'schemas', (SELECT coalesce(jsonb_agg(nspname ORDER BY nspname),'[]'::jsonb) FROM pg_namespace WHERE nspname IN ('public','private')),
 'tables_and_columns', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'column',column_name,'ordinal',ordinal_position,'data_type',data_type,'udt_name',udt_name,'nullable',is_nullable,'default',column_default,'identity',identity_generation,'generated',is_generated) ORDER BY table_schema,table_name,ordinal_position),'[]'::jsonb) FROM information_schema.columns WHERE table_schema IN ('public','private')),
 'constraints', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated) ORDER BY n.nspname,c.relname,k.conname),'[]'::jsonb) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private')),
 'indexes', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) ORDER BY schemaname,tablename,indexname),'[]'::jsonb) FROM pg_indexes WHERE schemaname IN ('public','private')),
 'rls', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) ORDER BY n.nspname,c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p')),
 'policies', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'with_check',with_check) ORDER BY schemaname,tablename,policyname),'[]'::jsonb) FROM pg_policies WHERE schemaname IN ('public','private')),
 'table_grants', (SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',grantee,'schema',table_schema,'table',table_name,'privilege',privilege_type,'grantable',is_grantable) ORDER BY grantee,table_schema,table_name,privilege_type),'[]'::jsonb) FROM information_schema.role_table_grants WHERE table_schema IN ('public','private')),
 'column_grants', (SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',grantee,'schema',table_schema,'table',table_name,'column',column_name,'privilege',privilege_type,'grantable',is_grantable) ORDER BY grantee,table_schema,table_name,column_name,privilege_type),'[]'::jsonb) FROM information_schema.role_column_grants WHERE table_schema IN ('public','private')),
 'default_privileges', (SELECT coalesce(jsonb_agg(jsonb_build_object('owner',r.rolname,'schema',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY r.rolname,n.nspname,d.defaclobjtype),'[]'::jsonb) FROM pg_default_acl d JOIN pg_roles r ON r.oid=d.defaclrole LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname IN ('public','private') OR d.defaclnamespace=0),
 'extensions', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) ORDER BY e.extname),'[]'::jsonb) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'functions', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'language',l.lanname,'security_definer',p.prosecdef,'volatility',p.provolatile,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname IN ('public','private')),
 'triggers', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname),'[]'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND NOT t.tgisinternal),
 'sequences', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'name',sequencename,'type',data_type,'start',start_value,'min',min_value,'max',max_value,'increment',increment_by,'cycle',cycle) ORDER BY schemaname,sequencename),'[]'::jsonb) FROM pg_sequences WHERE schemaname IN ('public','private')),
 'storage_buckets', (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) ORDER BY id),'[]'::jsonb) FROM storage.buckets),
 'storage_object_policies', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',policyname,'command',cmd,'roles',roles,'using',qual,'with_check',with_check) ORDER BY policyname),'[]'::jsonb) FROM pg_policies WHERE schemaname='storage' AND tablename='objects'),
 'product_case_check', jsonb_build_object('lower_exists',to_regclass('public.products') IS NOT NULL,'upper_exists',to_regclass('public."Products"') IS NOT NULL,'distinct',CASE WHEN to_regclass('public.products') IS NOT NULL AND to_regclass('public."Products"') IS NOT NULL THEN to_regclass('public.products')::oid <> to_regclass('public."Products"')::oid ELSE false END)
))::text;
